class Box {
    int count;
    Box(int count) {
        // 필드와 같은 이름의 매개변수를 구별해요.
        this.count = count;
    }
}

class Main {

    public static void main(String[] args) {
        // 전달한 숫자가 필드에 들어가도록 고치세요.
        int initial = 2;
        Box a = new Box(initial);
        System.out.println(a.count);
    }
}
